from math import comb

def calculate_R_Kn(n):
    if n < 3:
        return None

    # f(K_n): number of triangles (K3)
    f_Kn = comb(n, 3)

    # g(K_n): number of tetrahedra (K4)
    g_Kn = comb(n, 4)

    if f_Kn == 0:
        # This should only happen if n < 3, but good to check.
        return None

    # R(K_n) = g(K_n)^3 / f(K_n)^4
    R_Kn = (g_Kn**3) / (f_Kn**4)
    return R_Kn

results = {}
for n in range(3, 11):
    R_Kn = calculate_R_Kn(n)
    if R_Kn is not None:
        results[n] = R_Kn

print(results)

